use std::mem;
use std::os::unix::io::AsRawFd;

#[repr(C)]
struct Termios {
    c_iflag: u32,
    c_oflag: u32,
    c_cflag: u32,
    c_lflag: u32,
    c_line: u8,
    c_cc: [u8; 32],
    c_ispeed: u32,
    c_ospeed: u32,
}

#[repr(C)]
struct Winsize {
    ws_row: u16,
    ws_col: u16,
    ws_xpixel: u16,
    ws_ypixel: u16,
}

extern "C" {
    fn tcgetattr(fd: i32, termios_p: *mut Termios) -> i32;
    fn tcsetattr(fd: i32, optional_actions: i32, termios_p: *const Termios) -> i32;
    fn ioctl(fd: i32, request: u64, ...) -> i32;
}

const TIOCGWINSZ: u64 = 0x5413;
const TCSANOW: i32 = 0;

fn main() {
    let fd = std::io::stdin().as_raw_fd();

    // Get winsize
    let mut ws: Winsize = unsafe { mem::zeroed() };
    let res = unsafe { ioctl(fd, TIOCGWINSZ, &mut ws) };
    if res == 0 {
        println!("Rows: {}, Cols: {}", ws.ws_row, ws.ws_col);
    } else {
        println!("ioctl failed");
    }

    // Get and set termios
    let mut termios: Termios = unsafe { mem::zeroed() };
    let res = unsafe { tcgetattr(fd, &mut termios) };
    if res == 0 {
        println!("tcgetattr success");
    } else {
        println!("tcgetattr failed");
    }
}
EOF
rustc test_ffi.rs
./test_ffi
rm test_ffi.rs test_ffi"}

