{"command":"mkdir -p src
cat <<'EOF' > src/terminal.rs
use std::io::{self, Write};
use std::mem;
use std::os::unix::io::AsRawFd;

#[repr(C)]
#[derive(Clone)]
pub struct Termios {
    pub c_iflag: u32,
    pub c_oflag: u32,
    pub c_cflag: u32,
    pub c_lflag: u32,
    pub c_line: u8,
    pub c_cc: [u8; 32],
    pub c_ispeed: u32,
    pub c_ospeed: u32,
}

#[repr(C)]
pub struct Winsize {
    pub ws_row: u16,
    pub ws_col: u16,
    pub ws_xpixel: u16,
    pub ws_ypixel: u16,
}

extern "C" {
    pub fn tcgetattr(fd: i32, termios_p: *mut Termios) -> i32;
    pub fn tcsetattr(fd: i32, optional_actions: i32, termios_p: *const Termios) -> i32;
    pub fn ioctl(fd: i32, request: u64, ...) -> i32;
}

const TIOCGWINSZ: u64 = 0x5413;
const TCSANOW: i32 = 0;
const ICANON: u32 = 2;
const ECHO: u32 = 8;

pub struct Terminal {
    original_termios: Termios,
}

impl Terminal {
    pub fn new() -> io::Result<Self> {
        let fd = io::stdin().as_raw_fd();
        let mut termios: Termios = unsafe { mem::zeroed() };
        if unsafe { tcgetattr(fd, &mut termios) } != 0 {
            return Err(io::Error::last_os_error());
        }
        let original_termios = termios.clone();

        termios.c_lflag &= !(ICANON | ECHO);
        if unsafe { tcsetattr(fd, TCSANOW, &termios) } != 0 {
            return Err(io::Error::last_os_error());
        }

        print!("\x1b[?1049h"); // Switch to alternate screen
        io::stdout().flush()?;

        Ok(Terminal { original_termios })
    }

    pub fn size() -> (u16, u16) {
        let fd = io::stdin().as_raw_fd();
        let mut ws: Winsize = unsafe { mem::zeroed() };
        if unsafe { ioctl(fd, TIOCGWINSZ, &mut ws) } == 0 {
            (ws.ws_row, ws.ws_col)
        } else {
            (24, 80)
        }
    }
}

impl Drop for Terminal {
    fn drop(&mut self) {
        let fd = io::stdin().as_raw_fd();
        unsafe { tcsetattr(fd, TCSANOW, &self.original_termios) };
        print!("\x1b[?1049l"); // Switch back to main screen
        let _ = io::stdout().flush();
    }
}
EOF
"}

