use std::fs;
use std::path::{Path, PathBuf};
use std::process::Command;
use std::os::unix::fs::PermissionsExt;
use chrono::{DateTime, Local};

#[derive(Debug, Clone)]
pub struct FileInfo {
    pub name: String,
    pub path: PathBuf,
    pub is_dir: bool,
    pub size: u64,
    pub permissions: u32,
    pub modified: String,
    pub extension: String,
    pub is_dirty: bool,
}

pub fn get_files(path: &Path, show_hidden: bool) -> Vec<FileInfo> {
    let entries = match fs::read_dir(path) {
        Ok(e) => e,
        Err(_) => return Vec::new(),
    };

    let mut files = Vec::new();
    let git_status = get_git_status(path);

    for entry in entries {
        if let Ok(entry) = entry {
            let name = entry.file_name().into_string().unwrap_or_default();
            if !show_hidden && name.starts_with('.') {
                continue;
            }
            if name == "." || name == ".." {
                continue;
            }

            let metadata = entry.metadata().unwrap();
            let is_dir = metadata.is_dir();
            let size = metadata.len();
            let permissions = metadata.permissions().mode() & 0o777;
            let modified: DateTime<Local> = metadata.modified().unwrap().into();
            let modified_str = modified.format("%Y-%m-%d %H:%M").to_string();
            let extension = Path::new(&name)
                .extension()
                .and_then(|s| s.to_str())
                .unwrap_or("")
                .to_string();

            let mut is_dirty = false;
            if let Some(status) = git_status.get(&name) {
                if *status == 'M' || *status == '?' {
                    is_dirty = true;
                }
            }
            // For directories, check if they are "dirty"
            if is_dir {
               if let Some(status) = git_status.get(&(name.clone() + "/")) {
                   if *status == 'M' || *status == '?' {
                       is_dirty = true;
                   }
               }
            }

            files.push(FileInfo {
                name,
                path: entry.path(),
                is_dir,
                size,
                permissions,
                modified: modified_str,
                extension,
                is_dirty,
            });
        }
    }

