    files
}

fn sort_files(files: &mut [FileInfo]) {
    files.sort_by(|a, b| {
        if a.is_dir != b.is_dir {
            return b.is_dir.cmp(&a.is_dir);
        }
        natural_cmp(&a.name.to_lowercase(), &b.name.to_lowercase())
    });
}

fn natural_cmp(a: &str, b: &str) -> std::cmp::Ordering {
    // Simple natural sort implementation
    let a_chars: Vec<char> = a.chars().collect();
    let b_chars: Vec<char> = b.chars().collect();
    let mut i = 0;
    let mut j = 0;
    while i < a_chars.len() && j < b_chars.len() {
        if a_chars[i].is_digit(10) && b_chars[j].is_digit(10) {
            let mut a_num = 0u64;
            while i < a_chars.len() && a_chars[i].is_digit(10) {
                a_num = a_num * 10 + a_chars[i].to_digit(10).unwrap() as u64;
                i += 1;
            }
            let mut b_num = 0u64;
            while j < b_chars.len() && b_chars[j].is_digit(10) {
                b_num = b_num * 10 + b_chars[j].to_digit(10).unwrap() as u64;
                j += 1;
            }
            if a_num != b_num {
                return a_num.cmp(&b_num);
            }
        } else {
            if a_chars[i] != b_chars[j] {
                return a_chars[i].cmp(&b_chars[j]);
            }
            i += 1;
            j += 1;
        }
    }
    a_chars.len().cmp(&b_chars.len())
}

use std::collections::HashMap;

fn get_git_status(path: &Path) -> HashMap<String, char> {
    let output = Command::new("git")
        .arg("status")
        .arg("--porcelain")
        .current_dir(path)
        .output();

    let mut status_map = HashMap::new();
    if let Ok(output) = output {
        let stdout = String::from_utf8_lossy(&output.stdout);
        for line in stdout.lines() {
            if line.len() > 3 {
                let status = line.chars().next().unwrap();
                let status2 = line.chars().nth(1).unwrap();
                let file_path = &line[3..];
                let first_part = file_path.split('/').next().unwrap();

                let res_status = if status == '?' || status2 == '?' { '?' } else { 'M' };
                status_map.insert(first_part.to_string(), res_status);
                if file_path.contains('/') {
                    status_map.insert(first_part.to_string() + "/", res_status);
                }
            }
        }
    }
    status_map
}

pub fn get_git_branch(path: &Path) -> Option<String> {
    let output = Command::new("git")
        .arg("branch")
        .arg("--show-current")
        .current_dir(path)
        .output()
        .ok()?;
    if output.status.success() {
        let branch = String::from_utf8_lossy(&output.stdout).trim().to_string();
        if !branch.is_empty() {
            return Some(branch);
        }
    }
    None
}
