{"command":"cat <<'EOF' > src/app.rs
use crate::filesystem::{self, FileInfo};
use crate::terminal::Terminal;
use std::io::{self, Read, Write};
use std::path::PathBuf;

pub enum Mode {
    Normal,
    Search,
    Command,
}

pub struct App {
    pub current_dir: PathBuf,
    pub files: Vec<FileInfo>,
    pub selected_idx: usize,
    pub scroll_offset: usize,
    pub show_hidden: bool,
    pub mode: Mode,
    pub search_query: String,
    pub command_query: String,
    pub preview_open: bool,
    pub preview_horizontal: bool,
    pub exit: bool,
    pub last_working_dir: Option<PathBuf>,
}

impl App {
    pub fn new(start_dir: PathBuf) -> Self {
        let mut app = App {
            current_dir: start_dir.canonicalize().unwrap_or(start_dir),
            files: Vec::new(),
            selected_idx: 0,
            scroll_offset: 0,
            show_hidden: true,
            mode: Mode::Normal,
            search_query: String::new(),
            command_query: String::new(),
            preview_open: false,
            preview_horizontal: false,
            exit: false,
            last_working_dir: None,
        };
        app.refresh_files();
        app
    }

    pub fn refresh_files(&mut self) {
        self.files = filesystem::get_files(&self.current_dir, self.show_hidden);
        if self.selected_idx >= self.files.len() {
            self.selected_idx = if self.files.is_empty() { 0 } else { self.files.len() - 1 };
        }
    }

    pub fn run(&mut self) -> io::Result<()> {
        let mut stdin = io::stdin().bytes();
        let mut stdout = io::stdout();

        while !self.exit {
            self.render(&mut stdout)?;
            if let Some(Ok(b)) = stdin.next() {
                self.handle_input(b, &mut stdin)?;
            }
        }
        Ok(())
    }

    fn handle_input<R: Read>(&mut self, b: u8, stdin: &mut std::io::Bytes<R>) -> io::Result<()> {
        match self.mode {
            Mode::Normal => self.handle_normal_key(b, stdin),
            Mode::Search => self.handle_search_key(b, stdin),
            Mode::Command => self.handle_command_key(b, stdin),
        }
    }

    fn handle_normal_key<R: Read>(&mut self, b: u8, _stdin: &mut std::io::Bytes<R>) -> io::Result<()> {
        match b {
            b'j' => self.move_down(1),
            b'k' => self.move_up(1),
            b'g' => {
                // Wait for another 'g'
                // This is simplified, real 'gg' needs a timeout or another read
                self.selected_idx = 0;
                self.scroll_offset = 0;
            }
            b'G' => {
                if !self.files.is_empty() {
                    self.selected_idx = self.files.len() - 1;
                }
            }
            b'h' => {
                if let Some(parent) = self.current_dir.parent() {
                    self.current_dir = parent.to_path_buf();
                    self.refresh_files();
                    self.selected_idx = 0;
                    self.scroll_offset = 0;
                }
            }
            b'l' | 13 => { // 13 is Enter
                if let Some(file) = self.files.get(self.selected_idx) {
                    if file.is_dir {
                        self.current_dir = file.path.clone();
                        self.refresh_files();
                        self.selected_idx = 0;
                        self.scroll_offset = 0;
                    }
                }
            }
            b'v' => self.preview_open = !self.preview_open,
            b's' => self.preview_horizontal = !self.preview_horizontal,
            b':' => {
                self.mode = Mode::Command;
                self.command_query.clear();
            }
            b'/' => {
                self.mode = Mode::Search;
                self.search_query.clear();
            }
            127 => { // Backspace
                self.show_hidden = !self.show_hidden;
                self.refresh_files();
            }
            b'q' => {
               // Normal 'q' might not exit if it's part of :q
            }
            _ => {}
        }
        Ok(())
    }

    fn handle_search_key<R: Read>(&mut self, b: u8, _stdin: &mut std::io::Bytes<R>) -> io::Result<()> {
        match b {
            27 => self.mode = Mode::Normal, // Esc
            13 => self.mode = Mode::Normal, // Enter
            127 => { // Backspace
                self.search_query.pop();
            }
            _ => {
                if b.is_ascii_graphic() || b == b' ' {
                    self.search_query.push(b as char);
                    // Search and select first match
                    for (i, file) in self.files.iter().enumerate() {
                        if file.name.contains(&self.search_query) {
                            self.selected_idx = i;
                            break;
                        }
                    }
                }
            }
        }
        Ok(())
    }

    fn handle_command_key<R: Read>(&mut self, b: u8, _stdin: &mut std::io::Bytes<R>) -> io::Result<()> {
        match b {
            27 => self.mode = Mode::Normal, // Esc
            13 => { // Enter
                let cmd = self.command_query.clone();
                self.mode = Mode::Normal;
                if cmd == "q" {
                    self.exit = true;
                } else if cmd == "h" {
                    // Help
                }
            }
            127 => { // Backspace
                self.command_query.pop();
            }
            _ => {
                if b.is_ascii_graphic() || b == b' ' {
                    self.command_query.push(b as char);
                }
            }
        }
        Ok(())
    }

    fn move_down(&mut self, n: usize) {
        if !self.files.is_empty() {
            self.selected_idx = (self.selected_idx + n).min(self.files.len() - 1);
        }
    }

    fn move_up(&mut self, n: usize) {
        self.selected_idx = self.selected_idx.saturating_sub(n);
    }

    fn render<W: Write>(&mut self, stdout: &mut W) -> io::Result<()> {
        let (rows, cols) = Terminal::size();
        write!(stdout, "\x1b[H\x1b[J")?; // Clear screen

        // Draw path line
        let branch = filesystem::get_git_branch(&self.current_dir);
        let path_str = self.current_dir.to_string_lossy();
        write!(stdout, "\x1b[38;5;6m {}\x1b[m", path_str)?;
        if let Some(b) = branch {
            write!(stdout, " on \x1b[1;38;5;13m{}\x1b[m", b)?;
        }
        write!(stdout, "\r\n")?;

        // Draw search/command line
        match self.mode {
            Mode::Search => write!(stdout, " /{}\r\n", self.search_query)?,
            Mode::Command => write!(stdout, " :{}\r\n", self.command_query)?,
            Mode::Normal => write!(stdout, "\r\n")?,
        }

        // Draw file list
        let list_height = rows as usize - 3;
        if self.selected_idx >= self.scroll_offset + list_height {
            self.scroll_offset = self.selected_idx - list_height + 1;
        } else if self.selected_idx < self.scroll_offset {
            self.scroll_offset = self.selected_idx;
        }

        for i in 0..list_height {
            let file_idx = i + self.scroll_offset;
            if let Some(file) = self.files.get(file_idx) {
                let prefix = if file_idx == self.selected_idx { "> " } else { "  " };
                let color = if file.is_dir {
                    if file.is_dirty { "\x1b[38;5;1m" } else { "\x1b[38;5;14m" }
                } else {
                    if file.is_dirty { "\x1b[38;5;1m" } else { "\x1b[38;5;15m" }
                };

                let name = if self.mode == Mode::Search && !self.search_query.is_empty() && file.name.contains(&self.search_query) {
                    format!("\x1b[1m{}\x1b[22m", file.name)
                } else {
                    file.name.clone()
                };

                write!(stdout, "{}{}{}\x1b[m", prefix, color, name)?;
                // Move to column for date
                write!(stdout, "\x1b[{}G", cols - 20)?;
                write!(stdout, "{}{}\x1b[m\r\n", color, file.modified)?;
            } else {
                write!(stdout, "\r\n")?;
            }
        }

        // Draw status line
        if !self.files.is_empty() {
            let file = &self.files[self.selected_idx];
            let size_str = format_size(file.size);
            let status = if self.mode == Mode::Search {
                format!(" /{} - {} matches", self.search_query, 1) // matches count is wrong here
            } else {
                let ext = if file.is_dir { "".to_string() } else { format!("{} ", file.extension) };
                format!(" {}/{} {}{}{}", self.selected_idx + 1, self.files.len(), ext, size_str, file.permissions)
            };
            write!(stdout, "\x1b[7m{}\x1b[m", status)?;
        }

        stdout.flush()?;
        Ok(())
    }
}

fn format_size(size: u64) -> String {
    if size < 1024 {
        format!("{}B ", size)
    } else if size < 1024 * 1024 {
        format!("{}KB ", size / 1024)
    } else if size < 1024 * 1024 * 1024 {
        format!("{}MB ", size / (1024 * 1024))
    } else {
        format!("{}GB ", size / (1024 * 1024 * 1024))
    }
}
EOF
"}

