    pub fn new(start_dir: PathBuf) -> Self {
        let mut app = App {
            current_dir: start_dir.canonicalize().unwrap_or(start_dir),
            files: Vec::new(),
            selected_idx: 0,
            scroll_offset: 0,
            show_hidden: true,
            mode: Mode::Normal,
            search_query: String::new(),
            command_query: String::new(),
            preview_open: false,
            preview_horizontal: false,
            exit: false,
            last_working_dir: None,
        };
        app.refresh_files();
        app
    }

    pub fn refresh_files(&mut self) {
        self.files = filesystem::get_files(&self.current_dir, self.show_hidden);
        if self.selected_idx >= self.files.len() {
            self.selected_idx = if self.files.is_empty() { 0 } else { self.files.len() - 1 };
        }
    }

    pub fn run(&mut self) -> io::Result<()> {
        let mut stdin = io::stdin().bytes();
        let mut stdout = io::stdout();

        while !self.exit {
            self.render(&mut stdout)?;
            if let Some(Ok(b)) = stdin.next() {
                self.handle_input(b, &mut stdin)?;
            }
        }
        Ok(())
    }

    fn handle_input<R: Read>(&mut self, b: u8, stdin: &mut std::io::Bytes<R>) -> io::Result<()> {
        match self.mode {
            Mode::Normal => self.handle_normal_key(b, stdin),
            Mode::Search => self.handle_search_key(b, stdin),
            Mode::Command => self.handle_command_key(b, stdin),
        }
    }

    fn handle_normal_key<R: Read>(&mut self, b: u8, _stdin: &mut std::io::Bytes<R>) -> io::Result<()> {
        match b {
            b'j' => self.move_down(1),
            b'k' => self.move_up(1),
            b'g' => {
                // Wait for another 'g'
                // This is simplified, real 'gg' needs a timeout or another read
                self.selected_idx = 0;
                self.scroll_offset = 0;
            }
            b'G' => {
                if !self.files.is_empty() {
                    self.selected_idx = self.files.len() - 1;
                }
            }
            b'h' => {
                if let Some(parent) = self.current_dir.parent() {
                    self.current_dir = parent.to_path_buf();
                    self.refresh_files();
                    self.selected_idx = 0;
                    self.scroll_offset = 0;
                }
            }
            b'l' | 13 => { // 13 is Enter
                if let Some(file) = self.files.get(self.selected_idx) {
                    if file.is_dir {
                        self.current_dir = file.path.clone();
                        self.refresh_files();
                        self.selected_idx = 0;
                        self.scroll_offset = 0;
                    }
                }
            }
            b'v' => self.preview_open = !self.preview_open,
            b's' => self.preview_horizontal = !self.preview_horizontal,
            b':' => {
                self.mode = Mode::Command;
                self.command_query.clear();
            }
            b'/' => {
                self.mode = Mode::Search;
                self.search_query.clear();
            }
            127 => { // Backspace
                self.show_hidden = !self.show_hidden;
                self.refresh_files();
            }
            b'q' => {
               // Normal 'q' might not exit if it's part of :q
            }
            _ => {}
        }
        Ok(())
    }

    fn handle_search_key<R: Read>(&mut self, b: u8, _stdin: &mut std::io::Bytes<R>) -> io::Result<()> {
        match b {
            27 => self.mode = Mode::Normal, // Esc
            13 => self.mode = Mode::Normal, // Enter
            127 => { // Backspace
                self.search_query.pop();
            }
            _ => {
                if b.is_ascii_graphic() || b == b' ' {
                    self.search_query.push(b as char);
