    println!("# felix v2.16.1");
    println!("A simple TUI file manager with vim-like keymapping.");
    println!("");
    println!("## Usage");
    println!("`fx` => Show items in the current directory.");
    println!("`fx <directory path>` => Show items in the path.");
    println!("Both relative and absolute path available.");
    // ... add more from the original help
}

fn print_init() {
    println!(r#"# To be eval'ed in the calling shell
  eval "$(
    if [ -n "$XDG_RUNTIME_DIR" ]; then
      runtime_dir="$XDG_RUNTIME_DIR/felix"
    elif [ -n "$TMPDIR" ]; then
      runtime_dir="$TMPDIR/felix"
    else
      runtime_dir=/tmp/felix
    fi

    mkdir -p "$runtime_dir"

    # Clean up leftover LWD files
    find "$runtime_dir" -type f -and -mmin +1 -delete

    cat << EOF
fx() {{
  local RUNTIME_DIR="$runtime_dir"
  SHELL_PID=\$\$ command fx "\$@"

  if [ -f "\$RUNTIME_DIR/\$\$" ]; then
    cd "\$(cat "\$RUNTIME_DIR/\$\$")"
    rm "\$RUNTIME_DIR/\$\$"
  fi
}}
EOF
  )"#);
}
EOF
"}

