            let metadata = match entry.metadata() {
                Ok(m) => m,
                Err(_) => continue,
            };
            let is_dir = metadata.is_dir();
            let size = metadata.len();
            let permissions = metadata.permissions().mode() & 0o777;
            let modified_time = metadata.modified().unwrap_or(SystemTime::now());
