            let mut is_dirty = false;
            if let Some(status) = git_status.get(&name) {
                if *status == 'M' || *status == '?' {
                    is_dirty = true;
                }
            }
            if is_dir {
               if let Some(status) = git_status.get(&(name.clone() + "/")) {
