                        if b2 == b'[' {
                            if let Some(Ok(b3)) = stdin.next() {
                                match b3 {
                                    b'A' => self.move_up(1),
                                    b'B' => self.move_down(1),
                                    b'C' => self.handle_normal_key(b'l', &mut stdin)?,
