            b'p' => {
                if let Some(paths) = self.registers.get(&'0') {
                    for path in paths {
                        let mut target = self.current_dir.clone();
                        target.push(path.file_name().unwrap());
                        let _ = Command::new("cp").arg("-r").arg(path).arg(target).status();
