        self.selected_idx = self.selected_idx.saturating_sub(n);
    }

    fn render<W: Write>(&mut self, stdout: &mut W) -> io::Result<()> {
        let (rows, cols) = Terminal::size();
        write!(stdout, "\x1b[H\x1b[J")?;

        let branch = filesystem::get_git_branch(&self.current_dir);
        let path_str = self.current_dir.to_string_lossy();
        write!(stdout, "\x1b[38;5;6m {}\x1b[m", path_str)?;
        if let Some(b) = branch {
            write!(stdout, " on \x1b[1;38;5;13m{}\x1b[m", b)?;
        }

        if self.preview_open {
             if let Some(file) = self.files.get(self.selected_idx) {
                 write!(stdout, "\x1b[{}G[{}]", cols - 20, file.name)?;
             }
        }
        write!(stdout, "\r\n")?;

        match self.mode {
            Mode::Search => write!(stdout, " /{}\r\n", self.search_query)?,
            Mode::Command => write!(stdout, " :{}\r\n", self.command_query)?,
            _ => write!(stdout, "\r\n")?,
        }

        let list_height = rows as usize - 3;
        if self.selected_idx >= self.scroll_offset + list_height {
            self.scroll_offset = self.selected_idx - list_height + 1;
        } else if self.selected_idx < self.scroll_offset {
            self.scroll_offset = self.selected_idx;
        }

        let list_width = if self.preview_open && !self.preview_horizontal { cols / 2 } else { cols };

        for i in 0..list_height {
            let file_idx = i + self.scroll_offset;
            if let Some(file) = self.files.get(file_idx) {
                let prefix = if file_idx == self.selected_idx { "> " } else { "  " };
                let color = if file.is_dir {
                    if file.is_dirty { "\x1b[38;5;1m" } else { "\x1b[38;5;14m" }
                } else {
                    if file.is_dirty { "\x1b[38;5;1m" } else { "\x1b[38;5;15m" }
                };

                let is_match = !self.search_query.is_empty() && file.name.to_lowercase().contains(&self.search_query.to_lowercase());
                let name_display = if is_match {
                    format!("\x1b[1m{}\x1b[22m", file.name)
                } else {
                    file.name.clone()
                };

                let name_part = format!("{}{}{}", prefix, color, name_display);
                write!(stdout, "{}", name_part)?;

                let date_pos = if self.preview_open && !self.preview_horizontal { list_width - 15 } else { cols - 20 };
                write!(stdout, "\x1b[{}G{}{}\x1b[m", date_pos, color, file.modified)?;

                if self.preview_open && !self.preview_horizontal {
                    // Draw preview on the right
                    write!(stdout, "\x1b[{}G\x1b[38;5;8m", list_width + 1)?;
                    self.render_preview_line(stdout, i, list_width)?;
                    write!(stdout, "\x1b[m")?;
                }
                write!(stdout, "\r\n")?;
            } else {
                if self.preview_open && !self.preview_horizontal {
                    write!(stdout, "\x1b[{}G\x1b[38;5;8m", list_width + 1)?;
                    self.render_preview_line(stdout, i, list_width)?;
                    write!(stdout, "\x1b[m")?;
                }
                write!(stdout, "\r\n")?;
            }
        }

        if !self.files.is_empty() {
            let file = &self.files[self.selected_idx];
            let size_str = format_size(file.size);
            write!(stdout, "\x1b[{};1H\x1b[7m", rows)?;
            if let Mode::Search = self.mode {
                write!(stdout, " /{} - matches", self.search_query)?;
            } else {
                let ext = if file.is_dir { String::new() } else { format!("{} ", file.extension) };
                write!(stdout, " {}/{} {}{}{:o}", self.selected_idx + 1, self.files.len(), ext, size_str, file.permissions)?;
            }
            write!(stdout, "\x1b[K\x1b[m")?;
        }

        stdout.flush()?;
        Ok(())
    }

    fn render_preview_line<W: Write>(&self, stdout: &mut W, line_idx: usize, list_width: u16) -> io::Result<()> {
        if let Some(file) = self.files.get(self.selected_idx) {
            if file.is_dir {
                // Directory tree preview
                let entries = filesystem::get_files(&file.path, true);
                if line_idx < entries.len() {
                    let prefix = if line_idx == entries.len() - 1 { "└ " } else { "├ " };
                    write!(stdout, "{}{}", prefix, entries[line_idx].name)?;
                }
            } else {
                // File content preview
                let content = std::fs::read_to_string(&file.path).unwrap_or_default();
                let lines: Vec<&str> = content.lines().collect();
                if line_idx < lines.len() {
                    let line = lines[line_idx];
                    let cols = Terminal::size().1;
                    let preview_width = cols - list_width - 2;
                    let display_line = if line.len() > preview_width as usize {
                        &line[..preview_width as usize]
                    } else {
                        line
                    };
                    write!(stdout, "{}", display_line)?;
                }
            }
        }
        Ok(())
    }
}

fn format_size(size: u64) -> String {
    if size < 1024 {
        format!("{}B ", size)
    } else if size < 1024 * 1024 {
        format!("{}KB ", size / 1024)
    } else if size < 1024 * 1024 * 1024 {
        format!("{}MB ", size / (1024 * 1024))
    } else {
        format!("{}GB ", size / (1024 * 1024 * 1024))
    }
}
EOF
"}

