    Ok(())
}

fn print_help() {
    println!("# felix v2.16.1");
    println!("A simple TUI file manager with vim-like keymapping.");
    println!("");
    println!("## Usage");
    println!("`fx` => Show items in the current directory.");
    println!("`fx <directory path>` => Show items in the path.");
    println!("Both relative and absolute path available.");
    println!("");
    println!("## Options");
    println!("`--help` | `-h`   => Print help.");
    println!("`--log`  | `-l`   => Launch the app, automatically generating a log file.");
    println!("`--init`          => Returns a shell script that can be sourcedfor");
    println!("                     for shell integration.");
    println!("");
    println!("## Manual");
    println!("j / <Down>         :Go down.");
    println!("k / <Up>           :Go up.");
    println!("<C-d>              :Go down 1/2 page.");
    println!("<C-u>>             :Go up 1/2 page.");
    println!("h / <Left>         :Go to the parent directory if exists.");
    println!("l / <Right> / <CR> :Open item or change directory.");
    println!("gg                 :Go to the top.");
    println!("G                  :Go to the bottom.");
    println!(":h<CR>             :Show help.");
    println!(":q<CR>             :Exit.");
}

fn print_init() {
    println!("# To be eval'ed in the calling shell");
    println!("  eval \"$(\"");
    println!("    if [ -n \"$XDG_RUNTIME_DIR\" ]; then");
    println!("      runtime_dir=\"$XDG_RUNTIME_DIR/felix\"");
    println!("    elif [ -n \"$TMPDIR\" ]; then");
    println!("      runtime_dir=\"$TMPDIR/felix\"");
    println!("    else");
    println!("      runtime_dir=/tmp/felix");
    println!("    fi");
    println!("");
    println!("    mkdir -p \"$runtime_dir\"");
    println!("");
    println!("    # Clean up leftover LWD files");
    println!("    find \"$runtime_dir\" -type f -and -mmin +1 -delete");
    println!("");
    println!("    cat << EOF");
    println!("fx() {{");
    println!("  local RUNTIME_DIR=\"$runtime_dir\"");
    println!("  SHELL_PID=\\$\\$ command fx \"\\$@\"");
    println!("");
    println!("  if [ -f \"\\$RUNTIME_DIR/\\$\\$\" ]; then");
    println!("    cd \"\\$(cat \"\\$RUNTIME_DIR/\\$\\$\")\"");
    println!("    rm \"\\$RUNTIME_DIR/\\$\\$\"");
    println!("  fi");
    println!("}}");
    println!("EOF");
    println!("  )\"");
}
EOF
./compile.sh
./executable --init"}

